import * as THREE from './vendor/three.module.js';
export class BastionEffects {
 constructor(boss){this.boss=boss;this.config=boss.config;this.group=new THREE.Group();boss.scene.add(this.group);this.box=new THREE.BoxGeometry(1,1,1);this.particles=[];this.materials=new Map();this.strips=new THREE.InstancedMesh(this.box,new THREE.MeshBasicMaterial({color:'#ff634c',transparent:true,opacity:.56,depthWrite:false}),this.config.pulse.maxSurfaceSegments);this.strips.instanceMatrix.setUsage(THREE.DynamicDrawUsage);this.strips.frustumCulled=false;this.group.add(this.strips);this.dummy=new THREE.Object3D();this.rings=new Map();this.lines={};for(const id of['safe','greedy']){const line=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:this.config.debug[id+'Color'],transparent:true,opacity:.85,depthTest:false}));line.renderOrder=5;this.group.add(line);this.lines[id]=line;}this.playerHitbox=new THREE.Mesh(new THREE.SphereGeometry(this.config.projectiles.hitRadius,12,8),new THREE.MeshBasicMaterial({color:this.config.debug.hitboxColor,wireframe:true,depthTest:false}));this.group.add(this.playerHitbox);this.corridors=new THREE.InstancedMesh(new THREE.CylinderGeometry(1,1,1,8,1,true),new THREE.MeshBasicMaterial({color:'#ffffff',wireframe:true,transparent:true,opacity:.2,depthWrite:false,depthTest:false}),6);this.corridors.frustumCulled=false;this.group.add(this.corridors);this.vent=new THREE.PointLight('#ffa945',0,12);this.group.add(this.vent);this.setDebug(false);}
 reset(){for(const r of this.rings.values()){this.group.remove(r);r.geometry.dispose();}this.rings.clear();for(const p of this.particles)this.group.remove(p.mesh);this.particles=[];this.strips.count=0;}
 setDebug(value){this.debug=value;this.playerHitbox.visible=value;this.corridors.visible=value;if(this.boss.projectiles)this.boss.projectiles.debugMesh.visible=value;for(const l of Object.values(this.lines))l.material.opacity=value?1:.6;}
 impact(position,color='#6ffff0',strength=1){const c=this.config.feedback;for(let i=0;i<Math.ceil(c.sparks*strength)&&this.particles.length<c.maxParticles;i++){if(!this.materials.has(color))this.materials.set(color,new THREE.MeshBasicMaterial({color}));const mesh=new THREE.Mesh(this.box,this.materials.get(color));mesh.position.copy(position);mesh.scale.setScalar(c.size);this.group.add(mesh);const n=i*.61803398875*Math.PI*2;this.particles.push({mesh,age:0,life:c.life,velocity:new THREE.Vector3(Math.cos(n),.4+Math.sin(i*2)**2,Math.sin(n)).multiplyScalar(c.speed*strength),color});}}
 ring(w){let mesh=this.rings.get(w.id);if(mesh)return mesh;const n=this.config.pulse.groundSegments,g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(n*18),3));mesh=new THREE.Mesh(g,new THREE.MeshBasicMaterial({color:'#ff7353',transparent:true,opacity:.55,depthWrite:false,side:THREE.DoubleSide}));mesh.frustumCulled=false;this.group.add(mesh);this.rings.set(w.id,mesh);return mesh;}
 update(dt,time){const b=this.boss,c=this.config,p=c.pulse;if(b.player){this.playerHitbox.position.copy(b.player.position).addScaledVector(new THREE.Vector3().copy(b.player.motion.normal),c.projectiles.collisionHeight);}let strips=0;const active=new Set();for(const w of b.waves){active.add(w.id);const ring=this.ring(w);ring.position.copy(b.root.position);const attr=ring.geometry.attributes.position,n=p.groundSegments,outer=Math.min(p.maxRadius,w.age*p.groundSpeed+p.groundWidth/2),inner=Math.max(0,w.age*p.groundSpeed-p.groundWidth/2-p.groundSpeed*p.linger),rot=b.root.rotation.y,start=w.angle+p.gapHalfAngle+rot,arc=Math.PI*2-2*p.gapHalfAngle;let k=0;for(let i=0;i<n;i++){const a=start+i/n*arc,z=start+(i+1)/n*arc;for(const [r,t]of[[inner,a],[outer,a],[outer,z],[inner,a],[outer,z],[inner,z]]){attr.array[k++]=Math.sin(t)*r;attr.array[k++]=.13;attr.array[k++]=Math.cos(t)*r;}}attr.needsUpdate=true;ring.visible=inner<outer&&inner<=p.maxRadius;
   const scale=b.config.body.height/40,top=(w.age*p.surfaceSpeed+p.surfaceWidth/2)/scale,bottom=(w.age*p.surfaceSpeed-p.surfaceWidth/2-p.surfaceSpeed*p.linger)/scale;
   for(const part of b.model.parts){if(part.section.hidden)continue;const section=part.section,half=section.baseSize.map(v=>v/2),center=b.root.worldToLocal(part.node.getWorldPosition(new THREE.Vector3())),low=Math.max(center.y-half[1],bottom),high=Math.min(center.y+half[1],top);if(high<=low)continue;for(let face=0;face<4;face++)for(let j=0;j<p.surfaceSegmentsPerFace;j++){if(strips>=p.maxSurfaceSegments)break;const along=(j+.5)/p.surfaceSegmentsPerFace*2-1,x=face<2?(face===0?-half[0]:half[0]):along*half[0],z=face<2?along*half[2]:(face===2?-half[2]:half[2]),local=new THREE.Vector3(x,(low+high)/2-center.y,z),rootLocal=b.root.worldToLocal(part.node.localToWorld(local.clone()));if(Math.abs(Math.atan2(Math.sin(Math.atan2(rootLocal.x,rootLocal.z)-w.angle),Math.cos(Math.atan2(rootLocal.x,rootLocal.z)-w.angle)))<p.gapHalfAngle)continue;this.dummy.position.copy(part.node.localToWorld(local));this.dummy.quaternion.copy(section.body.quaternion);this.dummy.scale.set(face<2?.08:section.baseSize[0]/p.surfaceSegmentsPerFace,high-low,face<2?section.baseSize[2]/p.surfaceSegmentsPerFace:.08).multiplyScalar(scale);this.dummy.updateMatrix();this.strips.setMatrixAt(strips++,this.dummy.matrix);}}
  }this.strips.count=strips;this.strips.instanceMatrix.needsUpdate=true;for(const[id,m]of this.rings)if(!active.has(id)){this.group.remove(m);m.geometry.dispose();this.rings.delete(id);}
  let lineIndex=0;const paths=b.safePaths();for(const id of['safe','greedy']){const points=paths[id].map(p=>b.model.world(p));const g=this.lines[id].geometry;if(!g.attributes.position)g.setFromPoints(points);else{points.forEach((p,i)=>g.attributes.position.setXYZ(i,p.x,p.y,p.z));g.attributes.position.needsUpdate=true;g.computeBoundingSphere();}this.lines[id].visible=!b.dead;for(let i=1;i<points.length;i++){const a=points[i-1],end=points[i],axis=end.clone().sub(a);this.dummy.position.copy(a).add(end).multiplyScalar(.5);this.dummy.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),axis.clone().normalize());const radius=this.config.barrage[id+'Radius'];this.dummy.scale.set(radius,axis.length(),radius);this.dummy.updateMatrix();this.corridors.setMatrixAt(lineIndex,this.dummy.matrix);this.corridors.setColorAt(lineIndex++,new THREE.Color(this.config.debug[id+'Color']));}}
  this.corridors.count=lineIndex;this.corridors.instanceMatrix.needsUpdate=true;if(lineIndex)this.corridors.instanceColor.needsUpdate=true;this.vent.position.copy(b.aimPoint());this.vent.intensity=b.state.phase==='windup'?5+Math.sin(time*22)*3:0;if(b.state.phase==='windup'&&Math.floor(time*30)!==this.lastVent){this.lastVent=Math.floor(time*30);this.impact(b.aimPoint(),'#ffbf61',.25);}
  for(let i=this.particles.length-1;i>=0;i--){const a=this.particles[i];a.age+=dt;if(a.age>=a.life){this.group.remove(a.mesh);this.particles.splice(i,1);continue;}a.mesh.position.addScaledVector(a.velocity,dt);a.velocity.y-=c.feedback.gravity*dt;a.mesh.scale.setScalar(c.feedback.size*(1-a.age/a.life));}
 }
}
